    ["Major Vitality"] = "Vitalité majeure",
    ["Major Vitality grants 12% healing received and shield strength."] = "Vitalité majeure accorde 12 % aux soins reçus et à la puissance des boucliers.",
    ["Minor Aegis"] = "Égide mineure",
    ["Minor Aegis grants 5% damage reduction against PvE instance monsters."] = "Égide mineure réduit de 5 % les dégâts subis des monstres d'instances JcE.",
