    ["Minor Fortitude grants 15% Health Recovery."] = "Résilience mineure accorde 15 % de récupération de Santé.",
    ["Minor Heroism"] = "Héroïsme mineur",
    ["Minor Heroism grants 1 Ultimate every 1.5 seconds."] = "Héroïsme mineur accorde 1 point d'ultime toutes les 1,5 seconde.",
    ["Minor Intellect"] = "Intellect mineur",
    ["Minor Intellect grants 15% Magicka Recovery."] = "Intellect mineur accorde 15 % de récupération de Magie.",
