    ["Minor Mending grants 8% healing done by the recipient."] = "Guérison mineure accorde 8 % de soins produits au bénéficiaire.",
    ["Minor Prophecy"] = "Prophétie mineure",
    ["Minor Protection"] = "Protection mineure",
    ["Minor Protection grants 5% damage taken reduction."] = "Protection mineure réduit les dégâts subis de 5 %.",
